const listPerformanceTargets = `-- name: ListPerformanceTargets :many
SELECT t.id, t.uuid, t.organization_id, t.brand_id, t.target_org_id, t.metric, t.period_kind, t.period_start, t.period_end, t.value, t.currency, t.contract_ref, t.note, t.created_by_user_id, t.created_at, t.updated_at,
       o.name AS target_name,
       o.type AS target_type,
       a.actual::numeric AS actual,
       CASE WHEN a.actual IS NULL THEN NULL
            ELSE ROUND(a.actual / t.value * 100, 2)
       END::numeric AS achievement_pct,
       COUNT(*) OVER()::bigint AS total_count
FROM performance_targets t
JOIN organizations o ON o.id = t.target_org_id
LEFT JOIN LATERAL (
    SELECT SUM(pm.value) AS actual
    FROM performance_metrics_monthly pm
    WHERE pm.organization_id = t.target_org_id
      AND pm.metric = t.metric
      AND pm.currency IS NOT DISTINCT FROM t.currency
      AND pm.period >= to_char(t.period_start, 'YYYY-MM')
      AND pm.period < to_char(t.period_end, 'YYYY-MM')
) a ON true
WHERE t.brand_id = $1
  AND ($2::bigint[] IS NULL OR t.organization_id = ANY ($2::bigint[]))
  AND ($3::bigint[] IS NULL OR t.target_org_id = ANY ($3::bigint[]))
  AND (COALESCE(cardinality($4::text[]), 0) = 0 OR t.metric = ANY ($4::text[]))
  AND (COALESCE(cardinality($5::text[]), 0) = 0 OR t.period_kind = ANY ($5::text[]))
  AND ($6::date IS NULL OR t.period_end > $6::date)
  AND ($7::date IS NULL OR t.period_start < $7::date)
  AND ($8::text IS NULL OR o.name ILIKE '%' || $8::text || '%')
ORDER BY
  CASE WHEN NOT $9::bool THEN
    CASE $10::text
      WHEN 'target_name' THEN o.name
      WHEN 'metric' THEN t.metric
      WHEN 'period_kind' THEN t.period_kind
    END
  END ASC,
  CASE WHEN $9::bool THEN
    CASE $10::text
      WHEN 'target_name' THEN o.name
      WHEN 'metric' THEN t.metric
      WHEN 'period_kind' THEN t.period_kind
    END
  END DESC,
  CASE WHEN NOT $9::bool AND $10::text = 'period_start' THEN t.period_start END ASC,
  CASE WHEN $9::bool AND $10::text = 'period_start' THEN t.period_start END DESC,
  CASE WHEN NOT $9::bool AND $10::text = 'created_at' THEN t.created_at END ASC,
  CASE WHEN $9::bool AND $10::text = 'created_at' THEN t.created_at END DESC,
  CASE WHEN NOT $9::bool THEN
    CASE $10::text
      WHEN 'value' THEN t.value
      WHEN 'achievement_pct' THEN a.actual / t.value
    END
  END ASC NULLS LAST,
  CASE WHEN $9::bool THEN
    CASE $10::text
      WHEN 'value' THEN t.value
      WHEN 'achievement_pct' THEN a.actual / t.value
    END
  END DESC NULLS LAST,
  CASE WHEN $9::bool THEN t.id END DESC,
  t.id ASC
LIMIT $12 OFFSET $11
`

